-- create the request table sequence
CREATE SEQUENCE
  gs.seq_request
AS
  integer
OWNED BY
  gs.request.id;

-- offset the next id to be generated by a margin from migrated requests
SELECT
  setval('gs.seq_request', (SELECT 1000 + max("ID") FROM staging."Reviews"));

-- wire the sequence into the id column
ALTER TABLE gs.request
ALTER COLUMN id SET DEFAULT nextval('gs.seq_request');